import { readFileSync } from 'node:fs';
import { strict as assert } from 'node:assert';
import vm from 'node:vm';

const root = new URL('../', import.meta.url);
const read = path => readFileSync(new URL(path, root), 'utf8');

const dataCode = read('js/webcode-lessons.js');
const sandbox = { window: {} };
vm.createContext(sandbox);
vm.runInContext(dataCode, sandbox);

const lessons = sandbox.window.WEBCODE_LESSONS;
assert.equal(Array.isArray(lessons), true, 'lessons array exists');
assert.equal(lessons.length, 30, 'WebCode course includes thirty lessons');
assert.deepEqual(Array.from(lessons, l => l.id), Array.from({ length: 30 }, (_, i) => i + 1), 'lesson ids are sequential 1-30');
lessons.forEach(lessonItem => {
  assert.equal(lessonItem.durationMinutes, 90, `lesson ${lessonItem.id} is framed as 90 minutes`);
  assert.ok(lessonItem.starter?.html?.includes('<main'), `lesson ${lessonItem.id} has starter HTML`);
  assert.ok(lessonItem.starter?.css?.includes('background'), `lesson ${lessonItem.id} has starter CSS`);
  assert.ok(lessonItem.starter?.js?.includes('function'), `lesson ${lessonItem.id} has starter JavaScript`);
  assert.ok(lessonItem.lessonFlow.length >= 7, `lesson ${lessonItem.id} has a full guide flow`);
  const minimumExercises = [6, 7, 8, 9].includes(lessonItem.id) ? 6 : [2, 4, 5].includes(lessonItem.id) ? 7 : 8;
  assert.ok(lessonItem.exercises.length >= minimumExercises, `lesson ${lessonItem.id} has enough exercises`);
  assert.ok(lessonItem.vocabulary.length >= 4, `lesson ${lessonItem.id} has vocabulary`);
});

const lesson = lessons[0];
assert.equal(lesson.durationMinutes, 90, 'lesson is framed as 90 minutes');
assert.ok(lesson.title.includes('עמוד אמיתי') && lesson.title.includes('Blockly'), 'lesson has concise real Blockly page-builder title');
assert.ok(lesson.starter.html.includes('<button onclick="sayHello()">'), 'starter has working button');
assert.ok(lesson.starter.css.includes('border-radius'), 'starter includes visible styling');
assert.ok(lesson.starter.js.includes('getElementById("message")'), 'starter JS targets message id');
assert.ok(lesson.exercises.length >= 8, 'lesson includes many exercises');
assert.ok(lesson.lessonFlow.length >= 7, 'lesson includes full 90-minute guide flow');
assert.ok(lesson.vocabulary.some(v => v[0] === 'HTML'), 'vocabulary includes HTML');
assert.ok(lesson.vocabulary.some(v => v[0] === 'CSS'), 'vocabulary includes CSS');
assert.ok(lesson.vocabulary.some(v => v[0] === 'JavaScript'), 'vocabulary includes JavaScript');
assert.equal(lesson.mode, 'Real Blockly page builder', 'lesson 1 uses a real Blockly page builder');
assert.equal(lesson.realBlocklyBuilder, true, 'lesson 1 enables real Blockly workspace');
assert.ok(lesson.exercises.some(ex => ex.prompt.includes('גררו')), 'lesson 1 exercises require dragging blocks');

const lesson2 = lessons[1];
assert.equal(lesson2.durationMinutes, 90, 'lesson 2 is framed as 90 minutes');
assert.ok(lesson2.title.includes('סטודיו עיצוב'), 'lesson 2 focuses on real Blockly design studio');
assert.equal(lesson2.mode, 'Real Blockly design studio', 'lesson 2 uses real Blockly design studio mode');
assert.equal(lesson2.realBlocklyBuilder, true, 'lesson 2 enables real Blockly workspace');
assert.ok(lesson2.exercises.some(ex => ex.title.includes('Hover')), 'lesson 2 includes hover design exercise');
assert.ok(lesson2.exercises[0].title.includes('מתחילים פשוט'), 'lesson 2 starts simple before adding design blocks');
assert.equal(lesson2.exercises.length, 7, 'lesson 2 keeps only the non-redundant design exercises');
assert.ok(lesson2.vocabulary.some(v => v[0] === 'hover'), 'lesson 2 vocabulary includes hover');

const lesson3 = lessons[2];
assert.equal(lesson3.durationMinutes, 90, 'lesson 3 is framed as 90 minutes');
assert.equal(lesson3.title, 'כפתורים ופעולות קסם עם Blockly', 'lesson 3 title is clear and natural Hebrew');
assert.ok(lesson3.starter.html.includes('onclick="makeHappy()"'), 'lesson 3 has onclick event');
assert.ok(lesson3.starter.js.includes('classList.toggle("magic")'), 'lesson 3 includes classList toggle');
assert.ok(lesson3.exercises.length >= 8, 'lesson 3 includes many exercises');
assert.ok(!lesson3.exercises[0].prompt.includes('הרצה'), 'lesson 3 exercise 1 does not ask for a missing Run button');
assert.ok(lesson3.exercises[0].prompt.includes('כפתור “הפעילו קסם”') && lesson3.exercises[0].prompt.includes('בתצוגה החיה בצד שמאל'), 'lesson 3 exercise 1 points learners to the named live preview button');
assert.equal(lesson3.exercises[0].check.requiresPreviewButtonText, 'הפעילו קסם', 'lesson 3 exercise 1 requires clicking the preview magic button');
assert.ok(!lesson3.exercises[1].prompt.includes('הרצה'), 'lesson 3 exercise 2 does not ask for a missing Run button');
assert.equal(JSON.stringify(lesson3.exercises[1].check.changedBlocklyFields), JSON.stringify([{ type: 'web_button', field: 'LABEL', defaultValue: 'הפעילו קסם' }]), 'lesson 3 exercise 2 now requires changing only the visible button label');
assert.ok(!lesson3.exercises[1].check.unchangedBlocklyFields, 'lesson 3 exercise 2 no longer treats the button as the message-control block');
assert.ok(lesson3.exercises[1].hint.includes('בלוק “כפתור” קובע מה כתוב על הכפתור') && lesson3.exercises[1].hint.includes('בלוק פעולה'), 'lesson 3 exercise 2 explains button label versus click action');
assert.equal(lesson3.exercises[1].check.requiresPreviewButtonClick, true, 'lesson 3 exercise 2 requires trying the renamed preview button');
assert.equal(lesson3.exercises[2].check.requiresCodePeek, true, 'lesson 3 exercise 3 requires opening generated code peek');
assert.equal(lesson3.exercises[2].check.requiresCodeSelectionTab, 'html', 'lesson 3 exercise 3 requires HTML generated-code selection');
assert.deepEqual(Array.from(lesson3.exercises[2].check.requiresCodeSelectionBlockTypes), ['web_button'], 'lesson 3 exercise 3 requires selecting the button block');
assert.ok(lesson3.exercises[2].answerBox?.label.includes('מילת קוד') && lesson3.exercises[2].check.requiresCodeLineAnswer?.requiredSnippets?.includes('button') && lesson3.exercises[2].check.requiresCodeLineAnswer?.requiredSnippets?.includes('id') && lesson3.exercises[2].check.requiresCodeLineAnswer?.requiredSnippets?.includes('onclick'), 'lesson 3 exercise 3 accepts short code words actually visible in the selected HTML button line, including button, id, and onclick');
assert.equal(JSON.stringify(lesson3.exercises[3].check.changedBlocklyFields), JSON.stringify([{ type: 'web_action_message', field: 'TEXT', defaultValue: 'הודעה חדשה מהפעולה ✨' }]), 'lesson 3 exercise 4 requires changing the action-message text, separately from the button label');
assert.ok(lesson3.exercises[3].hint.includes('בלוק פעולה') && lesson3.exercises[3].hint.includes('message.textContent'), 'lesson 3 exercise 4 explains that click-message behavior belongs to the action block');
assert.equal(lesson3.exercises[3].check.requiresPreviewButtonText, 'הפעילו קסם', 'lesson 3 exercise 4 requires pressing the preview button after changing message');
assert.equal(lesson3.exercises[3].check.requiresPreviewMessageChangedFrom, 'כאן תופיע הודעה מהכפתור...', 'lesson 3 exercise 4 requires visible preview message change');
assert.ok(lesson3.exercises[3].check.blockFeedback.includes('חסר בלוק'), 'lesson 3 exercise 4 gives specific missing-action-block feedback');
assert.ok(lesson3.exercises[4].check.changedBlocklyFields?.some(rule => rule.type === 'web_action_emoji' && rule.field === 'EMOJI' && rule.defaultValue === '🤖'), 'lesson 3 exercise 5 requires changing the action emoji from default');
assert.equal(lesson3.exercises[4].check.requiresPreviewEmojiChangedFrom, '✨', 'lesson 3 exercise 5 requires the visible emoji to change in preview');
assert.ok(lesson3.exercises[5].check.changedBlocklyFieldsFromBaseline?.some(rule => rule.type === 'web_action_background' && rule.field === 'BG'), 'lesson 3 exercise 6 requires changing the background action from the entry baseline');
assert.equal(lesson3.exercises[5].check.ensureStarterBlocks?.[0]?.type, 'web_action_background', 'lesson 3 exercise 6 auto-adds the required background action block when missing');
assert.equal(lesson3.exercises[5].check.ensureStarterBlocks?.[0]?.after, 'web_button', 'lesson 3 exercise 6 inserts the background action after the button');
assert.equal(lesson3.exercises[5].check.exactBlockTypeCounts?.web_action_background, 1, 'lesson 3 exercise 6 rejects adding a second background action block');
assert.equal(lesson3.exercises[5].check.requiresPreviewButtonText, 'הפעילו קסם', 'lesson 3 exercise 6 requires pressing the preview button');
assert.equal(lesson3.exercises[6].check.requiresPreviewCardClass, 'magic', 'lesson 3 exercise 7 requires the preview card to enter magic mode');
assert.equal(lesson3.exercises[7].check.requiresCodeSelectionTab, 'js', 'lesson 3 exercise 8 requires selecting generated JavaScript');
assert.ok(lesson3.exercises[7].check.requiresCodeSelectionBlockTypes?.includes('web_action_emoji'), 'lesson 3 exercise 8 requires selecting an action block');
assert.ok(lesson3.exercises[3].check.fieldFeedback.includes('שנו את הטקסט'), 'lesson 3 exercise 4 gives specific unchanged-text feedback');
assert.ok(lesson3.vocabulary.some(v => v[0] === 'onclick'), 'lesson 3 vocabulary includes onclick');

const lessons4to24 = lessons.slice(3, 24);
lessons4to24.forEach(lessonItem => {
  assert.equal(lessonItem.realBlocklyBuilder, true, `lesson ${lessonItem.id} uses real draggable Blockly blocks`);
  assert.equal(lessonItem.blocklyLessonBuilder, true, `lesson ${lessonItem.id} uses the lesson-specific Blockly builder`);
  assert.equal(lessonItem.bridgeBlocks.length, 0, `lesson ${lessonItem.id} does not expose legacy helper/code-card buttons`);
  assert.ok(lessonItem.mode.includes('Real Blockly full rework'), `lesson ${lessonItem.id} is marked as a full real Blockly rework`);
  assert.ok(lessonItem.progressionStage.includes('בלוקים אמיתיים'), `lesson ${lessonItem.id} stays in the block-first phase`);
  assert.ok(lessonItem.blocklyBlocks.length >= 5, `lesson ${lessonItem.id} has several draggable lesson blocks`);
  assert.ok(lessonItem.blocklyBlocks.some(block => block.args0?.length), `lesson ${lessonItem.id} has editable fields/dropdowns inside lesson blocks`);
  assert.equal(lessonItem.exercises.length, [6, 8, 9].includes(lessonItem.id) ? 6 : [4, 5, 7].includes(lessonItem.id) ? 7 : 8, `lesson ${lessonItem.id} has the reviewed exercise count`);
  lessonItem.exercises.forEach(ex => {
    assert.ok(ex.prompt.includes('בלוק') || ex.prompt.includes('תצוגה') || ex.prompt.includes('קוד שנוצר') || ex.prompt.includes('תיבת הקוד'), `lesson ${lessonItem.id} exercise ${ex.id} is phrased around blocks/preview/generated code`);
    assert.ok(ex.noCheck || (ex.check && Object.keys(ex.check).length > 0), `lesson ${lessonItem.id} exercise ${ex.id} has a validator or is explicitly no-check`);
  });
  assert.ok(!lessonItem.exercises[0].prompt.includes('הריצו'), `lesson ${lessonItem.id} exercise 1 is not a fake run-the-already-running-preview task`);
  assert.ok(lessonItem.exercises[0].check.blockTypes?.length, `lesson ${lessonItem.id} exercise 1 requires a real block action`);
  const blockChecks = lessonItem.exercises.filter(ex => ex.check.blockTypes?.length);
  assert.ok(blockChecks.length >= (lessonItem.id === 4 ? 5 : [6, 8, 9].includes(lessonItem.id) ? 5 : lessonItem.id === 7 ? 6 : 6), `lesson ${lessonItem.id} requires connected Blockly blocks in most exercises`);
  const final = lessonItem.exercises.at(-1).check;
  if (lessonItem.id !== 4) {
    assert.equal(final.requiresCodePeek, true, `lesson ${lessonItem.id} final exercise requires generated-code peek`);
    assert.ok(final.requiresCodeSelectionBlockTypes?.length >= 1, `lesson ${lessonItem.id} final exercise requires selecting a connected generated-code block`);
  }
});

const lesson4 = lessons[3];
assert.equal(lesson4.durationMinutes, 90, 'lesson 4 is framed as 90 minutes');
assert.ok(lesson4.title.includes('קלט'), 'lesson 4 focuses on user input');
assert.ok(lesson4.title.includes('ברכות'), 'lesson 4 is framed as a fun personal generator');
assert.ok(lesson4.starter.html.includes('id="nameInput"'), 'lesson 4 has name input');
assert.ok(lesson4.starter.js.includes('.value'), 'lesson 4 reads input value');
assert.ok(lesson4.exercises[0].prompt.includes('גררו') && lesson4.exercises[0].check.blockTypes?.includes('lesson_4_name_label'), 'lesson 4 uses a draggable block for the first input-label change');
assert.ok(lesson4.exercises[1].check.blockTypes?.includes('lesson_4_topic_label'), 'lesson 4 uses a draggable block for the topic-label change');
assert.ok(lesson4.exercises[3].prompt.includes('לחצו על כפתור הברכה'), 'lesson 4 result-sentence exercise tells learners to press the preview button');
assert.equal(lesson4.exercises[3].check.requiresPreviewButtonClick, true, 'lesson 4 result-sentence exercise requires pressing the preview button');
assert.ok(lesson4.exercises[3].check.requiresPreviewResultFromBlockOutput?.some(rule => rule.type === 'lesson_4_sentence'), 'lesson 4 result-sentence exercise checks the preview result contains the generated sentence text');
const lesson4EndingBlock = lesson4.blocklyBlocks.find(block => block.type === 'lesson_4_result_word');
assert.equal(lesson4EndingBlock.label, 'אימוג׳י סיום בתוצאה', 'lesson 4 ending block is named for the emoji it changes');
assert.equal(lesson4EndingBlock.find, 'רעיונות נוצצים 🚀', 'lesson 4 ending block finds the actual starter result ending');
assert.equal(lesson4EndingBlock.replace, 'רעיונות נוצצים {{TEXT}}', 'lesson 4 ending block replaces the visible result ending');
assert.ok(lesson4.exercises[4].check.requiresPreviewResultFromBlockOutput?.some(rule => rule.type === 'lesson_4_result_word'), 'lesson 4 ending block exercise checks the visible preview result');
assert.equal(lesson4.exercises.length, 7, 'lesson 4 keeps the generated-code reading exercise plus optional challenge');
assert.equal(lesson4.exercises[5].check.requiresCodePeek, true, 'lesson 4 generated-code reading exercise requires opening code peek');
assert.ok(lesson4.exercises[5].check.jsIncludes?.includes('getElementById("nameInput").value'), 'lesson 4 generated-code reading exercise checks the nameInput value line exists');
assert.equal(lesson4.exercises.at(-1).optional, true, 'lesson 4 final challenge is optional/skippable');
assert.ok(['lesson_4_name_label','lesson_4_topic_label','lesson_4_button_text','lesson_4_sentence','lesson_4_result_word'].every(type => lesson4.exercises.at(-1).blocklyStarterXml?.includes(type)), 'lesson 4 optional challenge provides the full connected starter block program to fix');
assert.equal(lesson4.exercises.at(-1).check.exactBlocklyFields?.[0]?.value, '🎉', 'lesson 4 optional challenge checks the exact starter-block fix');
assert.ok(lesson4.vocabulary.some(v => v[0] === 'input'), 'lesson 4 vocabulary includes input');

const lesson5 = lessons[4];
assert.equal(lesson5.durationMinutes, 90, 'lesson 5 is framed as 90 minutes');
assert.ok(lesson5.title.includes('חידון'), 'lesson 5 focuses on quiz building');
assert.ok(lesson5.starter.html.includes('answerInput'), 'lesson 5 uses a text input so quizzes are not limited to yes/no choices');
assert.ok(!lesson5.starter.html.includes("chooseAnswer('yes')"), 'lesson 5 no longer uses fixed yes/no choices');
assert.ok(lesson5.starter.js.includes('const answer = document.getElementById("answerInput").value.trim()'), 'lesson 5 reads the typed answer from the preview');
assert.ok(lesson5.starter.js.includes('if (answer === "CSS")'), 'lesson 5 includes a text-answer if condition');
assert.ok(lesson5.starter.js.includes('else'), 'lesson 5 includes else branch');
assert.ok(lesson5.exercises[0].check.blocklyFieldsContaining?.some(rule => rule.type === 'lesson_5_question' && rule.field === 'TEXT' && rule.includes === '?'), 'lesson 5 question exercise requires a question mark in the question text');
const lesson5AnswerBlock = lesson5.blocklyBlocks.find(block => block.type === 'lesson_5_answer');
assert.ok(lesson5AnswerBlock?.args0?.some(arg => arg.type === 'field_input' && arg.name === 'TEXT'), 'lesson 5 correct-answer block is free text, not a dropdown');
assert.ok(!lesson5AnswerBlock?.args0?.some(arg => arg.type === 'field_dropdown'), 'lesson 5 correct-answer block avoids limiting answers to dropdown options');
assert.ok(lesson5.exercises[1].check.nonEmptyBlocklyFields?.some(rule => rule.type === 'lesson_5_answer' && rule.field === 'TEXT'), 'lesson 5 answer exercise rejects empty answers');
assert.ok(lesson5.exercises[1].check.generatedBlockOutputs?.some(rule => rule.type === 'lesson_5_answer' && rule.target === 'js'), 'lesson 5 answer exercise checks the generated JS condition matches the typed block value');
assert.equal(lesson5.exercises[1].check.requiresPreviewButtonClick, true, 'lesson 5 answer exercise requires trying an answer in the preview');
assert.ok(lesson5.exercises[1].check.requiresPreviewFilledInputs?.includes('answerInput'), 'lesson 5 answer exercise requires typing an answer before checking the preview');
assert.ok(!lesson5.exercises[1].check.requiresPreviewInputMatchesBlockFields, 'lesson 5 answer exercise does not require the preview answer to match the block answer exactly');
assert.ok(!lesson5.exercises[1].check.requiresPreviewFeedbackClass, 'lesson 5 answer exercise does not require the preview answer to be accepted as correct');
const lesson5ButtonColorBlock = lesson5.blocklyBlocks.find(block => block.type === 'lesson_5_button_style');
assert.ok(lesson5ButtonColorBlock?.args0?.[0]?.options?.length <= 6, 'lesson 5 button-color menu adds only a few options');
assert.ok(JSON.stringify(lesson5ButtonColorBlock?.args0?.[0]?.options || []).includes('#2563eb') && JSON.stringify(lesson5ButtonColorBlock?.args0?.[0]?.options || []).includes('#db2777') && JSON.stringify(lesson5ButtonColorBlock?.args0?.[0]?.options || []).includes('#facc15'), 'lesson 5 button-color menu includes three extra useful color choices');
assert.equal(lesson5.exercises.length, 7, 'lesson 5 keeps seven exercises with one short code-writing task at the end');
assert.equal(lesson5.exercises.at(-1).id, 7, 'lesson 5 final exercise is the short code-writing task');
assert.ok(lesson5.exercises.at(-1).check.requiresCodePeek, 'lesson 5 still ends with a generated-code writing exercise');
assert.ok(lesson5.starter.html.includes('id="colorChoice"'), 'lesson 5 includes a separate color choice input for the extra condition');
const lesson5ColorBlock = lesson5.blocklyBlocks.find(block => block.type === 'lesson_5_chosen_background');
assert.ok(lesson5ColorBlock?.replace?.includes('colorChoice === "{{COLOR}}"') && lesson5ColorBlock?.replace?.includes('document.body.style.background = "{{BG}}"'), 'lesson 5 has a flexible separate color condition block that changes the page background');
assert.ok(lesson5ColorBlock?.args0?.some(arg => arg.name === 'COLOR' && arg.options?.length >= 3), 'lesson 5 color condition lets learners choose which color to check, not only red');
assert.ok(lesson5.exercises[2].title.includes('הודעות אם נכון / אחרת'), 'lesson 5 combines success and else message work into one exercise');
assert.ok(lesson5.exercises[2].check.blockTypes?.includes('lesson_5_success') && lesson5.exercises[2].check.blockTypes?.includes('lesson_5_wrong'), 'combined message exercise requires both success and wrong blocks');
assert.ok(lesson5.exercises[3].title.includes('בחירת צבע') && lesson5.exercises[3].check.blockTypes?.includes('lesson_5_chosen_background'), 'lesson 5 exercise 4 adds a flexible separate color-choice condition');
assert.ok(lesson5.exercises[4].title.includes('צבע כפתור') && lesson5.exercises[4].check.blockTypes?.includes('lesson_5_button_style'), 'lesson 5 keeps button-color styling after the new condition');
assert.ok(lesson5.exercises[5].title.includes('דיבאג הודעות') && lesson5.exercises[5].blocklyStarterXml?.includes('כמעט! רמז') && lesson5.exercises[5].blocklyStarterXml?.includes('נכון! JavaScript'), 'lesson 5 exercise 6 is a self-contained debug task with swapped correct/wrong messages');
assert.ok(lesson5.exercises[5].check.exactBlocklyFields?.some(rule => rule.type === 'lesson_5_success' && rule.value.includes('נכון!')) && lesson5.exercises[5].check.exactBlocklyFields?.some(rule => rule.type === 'lesson_5_wrong' && rule.value.includes('כמעט!')), 'lesson 5 debug task requires putting success and wrong messages back in the correct blocks');
assert.ok(lesson5.exercises.at(-1).title.includes('כותבים קטע קוד קצר') && lesson5.exercises.at(-1).answerBox?.label.includes('קוד'), 'lesson 5 final exercise requires writing one short JavaScript condition fragment');
assert.equal(lesson5.exercises.at(-1).check.requiresCodeSelectionTab, 'js', 'lesson 5 final code-writing exercise requires selecting generated JavaScript');
assert.ok(lesson5.exercises.at(-1).check.requiresCodeLineAnswer?.requiredSnippets?.includes('answer ==='), 'lesson 5 final code-writing exercise asks learners to type a short comparison fragment');
assert.ok(!lesson5.exercises[2].check.requiresPreviewInputMatchesBlockFields, 'lesson 5 combined message exercise does not tell learners to copy the correct-answer block text');
