assert.ok(lesson5.vocabulary.some(v => v[0] === 'if'), 'lesson 5 vocabulary includes if');
assert.ok(lesson5.vocabulary.some(v => v[0] === 'answer'), 'lesson 5 vocabulary names the typed answer');

const lesson6 = lessons[5];
assert.equal(lesson6.durationMinutes, 90, 'lesson 6 is framed as 90 minutes');
assert.ok(lesson6.title.includes('ניקוד') || lesson6.title.includes('score'), 'lesson 6 focuses on scoring');
assert.ok(lesson6.starter.html.includes("chooseAnswer('yes')"), 'lesson 6 keeps scoring on fixed choices');
assert.ok(!lesson6.starter.html.includes('answerInput'), 'lesson 6 avoids typed-answer matching while teaching score');
assert.ok(lesson6.starter.js.includes('const startScore = 0') && lesson6.starter.js.includes('let score = startScore'), 'lesson 6 initializes score from a reusable starting-score value');
assert.ok(lesson6.starter.js.includes('const pointsForCorrect = 0'), 'lesson 6 starter does not add points before the add-points block is connected');
assert.ok(lesson6.starter.js.includes('pointsForCorrect === 1 ? "נקודה" : "נקודות"'), 'lesson 6 success message uses singular/plural points wording');
assert.ok(lesson6.starter.js.includes('pointsForCorrect === 1 ? "נכון! קיבלת נקודה ⭐"'), 'lesson 6 default success message says נקודה without the number for one point');
assert.ok(lesson6.starter.js.includes('נכון! קיבלת " + pointsForCorrect') && lesson6.starter.js.includes('נקודות'), 'lesson 6 default success message includes the actual points value for multiple points');
assert.ok(!lesson6.starter.js.includes('answeredCorrectly'), 'lesson 6 lets learners press the correct answer repeatedly without anti-spam lockout');
assert.ok(lesson6.starter.js.includes('if (choice === "yes")'), 'lesson 6 correct-answer branch remains simple and repeatable');
assert.ok(lesson6.starter.js.includes('score = startScore;') && lesson6.starter.js.includes('feedback.className = "try-again"'), 'lesson 6 reset button returns to the starting score and clears success state');
assert.ok(lesson6.blocklyBlocks.some(block => block.type === 'lesson_6_start_score'), 'lesson 6 keeps the original starting-score block');
assert.ok(lesson6.exercises[0].prompt.includes('כבר מחובר בקוד ההתחלה') && lesson6.exercises[0].prompt.includes('ערך אחר מ־0'), 'lesson 6 start-score exercise starts with the block connected and asks only for a value change');
assert.ok(lesson6.exercises[0].blocklyStarterXml?.includes('lesson_6_start_score'), 'lesson 6 start-score exercise preloads the starting-score block');
assert.ok(lesson6.exercises[0].check.fieldFeedback.includes('עדיין על 0'), 'lesson 6 start-score error points to the actual required value change');
const lesson6StartScoreBlock = lesson6.blocklyBlocks.find(block => block.type === 'lesson_6_start_score');
const lesson6PlusBlock = lesson6.blocklyBlocks.find(block => block.type === 'lesson_6_plus');
assert.equal(lesson6StartScoreBlock.find, 'const startScore = 0;', 'lesson 6 start-score block changes only the starting score constant');
assert.equal(lesson6StartScoreBlock.replace, 'const startScore = {{N}};', 'lesson 6 start-score block does not change per-answer scoring');
assert.equal(lesson6PlusBlock.find, 'const pointsForCorrect = 0;', 'lesson 6 add-points block changes the points value used by scoring and feedback');
assert.equal(lesson6PlusBlock.replace, 'const pointsForCorrect = {{N}};', 'lesson 6 add-points block keeps scoring and default message in sync');
assert.ok(lesson6.blocklyBlocks.some(block => block.type === 'lesson_6_plus'), 'lesson 6 has a Blockly block for score increment size');
assert.ok(lesson6.blocklyBlocks.some(block => block.type === 'lesson_6_message' && block.find === 'const successMessage = "";'), 'lesson 6 message block overrides the dynamic default success message only when connected');
